// 購入金額と会員ランクで送料を決める
// ここを変えてみよう:amount を 2999 / 3000 / 5000 に、rank を "GOLD" や "NORMAL" に
int amount = 2980;
String rank = "SILVER";

int fee;
if ("GOLD".equals(rank)) {
    fee = 0;                       // ゴールド会員は常に送料無料
} else if (amount >= 5000) {
    fee = 0;                       // 5000円以上は誰でも無料
} else if ("SILVER".equals(rank) && amount >= 3000) {
    fee = 0;                       // シルバー会員は3000円以上で無料
} else {
    fee = 500;
}
System.out.println("購入金額: " + amount + "円 / ランク: " + rank);
System.out.println("送料: " + fee + "円");
System.out.println("お支払い合計: " + (amount + fee) + "円");

// 曜日番号(1=月 … 7=日)を switch 式で分類する
// ここを変えてみよう:day を 1〜7 や 0、8 にしてみる。default の行を消すとどうなる?
int day = 6;

String type = switch (day) {
    case 1, 2, 3, 4, 5 -> "平日";
    case 6, 7 -> "休日";
    default -> "不正な曜日番号";
};

String name = switch (day) {
    case 1 -> "月"; case 2 -> "火"; case 3 -> "水"; case 4 -> "木";
    case 5 -> "金"; case 6 -> "土"; case 7 -> "日";
    default -> {
        System.out.println("※ 1〜7 で指定してください");
        yield "?";                 // ブロックの中では yield で値を返す
    }
};
System.out.println(day + " → " + name + "曜日は " + type);

// フォールスルーの罠:従来の switch 文で break を忘れると……
// ここを変えてみよう:case 6 の後に break; を足す / day を 7 や 3 にする
int day = 6;

System.out.println("--- 従来の switch 文(break 忘れ)---");
switch (day) {
    case 6:
        System.out.println("土曜日");
    case 7:
        System.out.println("日曜日");
        break;
    default:
        System.out.println("平日");
}

System.out.println("--- アロー構文(落ちていかない)---");
switch (day) {
    case 6 -> System.out.println("土曜日");
    case 7 -> System.out.println("日曜日");
    default -> System.out.println("平日");
}

// 文字列の比較は equals。== は「同じオブジェクトか」を見るだけ
// ここを変えてみよう:input を null にしてみる(input.equals は NPE、"GOLD".equals は false になる)
String part = "GOL";
String input = part + "D";      // 実行時に組み立てた "GOLD"(ユーザー入力のつもり)

System.out.println("input == \"GOLD\"      → " + (input == "GOLD"));
System.out.println("input.equals(\"GOLD\") → " + input.equals("GOLD"));
System.out.println("\"GOLD\".equals(input) → " + "GOLD".equals(input));   // null でも安全

String label = (input == null) ? "未入力" : switch (input) {   // null を switch に渡すと NPE なので先にはじく
    case "GOLD" -> "ゴールド会員";
    case "SILVER" -> "シルバー会員";
    default -> "一般会員";
};
System.out.println("会員区分: " + label);

